WITH src AS (SELECT *, CASE WHEN city = 'London' THEN 1 ELSE 0 END AS is_london FROM stores WHERE city = 'Bangkok' OR YEAR(opened_date) >= 2024), is_london_bucket_summary AS (SELECT CASE WHEN is_london >= 90 THEN 'high' WHEN is_london >= 38 THEN 'mid' ELSE 'low' END AS is_london_bucket, COUNT(CASE WHEN region = 'North' THEN 1 END) AS north_count FROM src GROUP BY CASE WHEN is_london >= 90 THEN 'high' WHEN is_london >= 38 THEN 'mid' ELSE 'low' END) SELECT is_london_bucket, north_count FROM is_london_bucket_summary ORDER BY north_count DESC, is_london_bucket LIMIT 5
